mapper.select:
SELECT id FROM version_release WHERE workspace_id = #{workspaceId} AND version_id = #{versionId}
  AND result = 'success' AND environment = 'production' AND operation IN ('deploy', 'redeploy')
ORDER BY id FOR UPDATE

SELECT id FROM version_release_plan WHERE workspace_id = #{workspaceId}
  AND (version_id = #{versionId}
       OR id IN (SELECT plan_id FROM version_release_plan_version
                 WHERE workspace_id = #{workspaceId} AND version_id = #{versionId}))
ORDER BY id FOR UPDATE

SELECT  FROM task
WHERE id = #{id}
  AND workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})

mapper.sql:
WHERE t.deleted_at IS NULL AND (t.owner_user_id = #{userId}
OR (t.owner_user_id IS NULL AND t.owner = #{displayName}) )
AND (m.role IN ('owner', 'admin', 'viewer') OR NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = t.workspace_id AND pm.project_id = t.req_id AND pm.user_id = #{userId} AND pm.access = 'none')) AND t.board_column != 'done'
AND (t.title LIKE CONCAT('%', #{q}, '%') OR t.description LIKE CONCAT('%', #{q}, '%') OR t.note LIKE CONCAT('%', #{q}, '%') OR EXISTS (SELECT 1 FROM category cg WHERE cg.id = t.category_id AND cg.workspace_id = t.workspace_id AND cg.name LIKE CONCAT('%', #{q}, '%')) OR EXISTS (SELECT 1 FROM requirement r WHERE r.id = t.req_id AND r.workspace_id = t.workspace_id AND r.name LIKE CONCAT('%', #{q}, '%')) OR EXISTS (SELECT 1 FROM task_tag tt JOIN tag g ON g.id = tt.tag_id WHERE tt.task_id = t.id AND tt.workspace_id = t.workspace_id AND g.name LIKE CONCAT('%', #{q}, '%')) OR EXISTS (SELECT 1 FROM attachment a WHERE a.target_id = t.id AND a.target_kind = 'task' AND a.workspace_id = t.workspace_id AND a.filename LIKE CONCAT('%', #{q}, '%')))
AND t.priority IN #{p}
AND t.category_id IN #{c}
AND (
t.req_id IS NULL t.req_id = #{r}
)
AND EXISTS (SELECT 1 FROM task_tag tt JOIN tag tg ON tg.id = tt.tag_id WHERE tt.task_id = t.id AND tg.name IN #{tg})
AND t.item_type IN #{tp}
AND (
NOT EXISTS (SELECT 1 FROM version_task vt WHERE vt.task_id = t.id AND vt.workspace_id = t.workspace_id)
EXISTS (SELECT 1 FROM version_task vt WHERE vt.task_id = t.id AND vt.workspace_id = t.workspace_id AND vt.version_id = #{v})
)
AND t.is_blocked = 1
AND t.board_column <> 'done' AND t.due_date < #{today} AND NOT EXISTS (SELECT 1 FROM board_column bc WHERE bc.workspace_id = t.workspace_id AND bc.id = t.board_column AND bc.processing_rule = 'ended') AND t.board_column <> 'done' AND t.due_date = #{today} AND NOT EXISTS (SELECT 1 FROM board_column bc WHERE bc.workspace_id = t.workspace_id AND bc.id = t.board_column AND bc.processing_rule = 'ended') AND t.board_column <> 'done' AND t.due_date >= #{today} AND t.due_date <= DATE_ADD(#{today}, INTERVAL 3 DAY) AND NOT EXISTS (SELECT 1 FROM board_column bc WHERE bc.workspace_id = t.workspace_id AND bc.id = t.board_column AND bc.processing_rule = 'ended') AND 1 = 0
AND ((t.board_column <> 'done' AND t.due_date IS NOT NULL AND t.due_date <= #{today} AND NOT EXISTS (SELECT 1 FROM board_column bc WHERE bc.workspace_id = t.workspace_id AND bc.id = t.board_column AND bc.processing_rule = 'ended')) OR (t.board_column = 'doing' AND t.priority = 'P0'))

mapper.select:
SELECT  FROM task
WHERE deleted_at IS NOT NULL AND deleted_at < #{cutoff}
  AND NOT EXISTS (
    SELECT 1 FROM version_release_plan_task pt
    WHERE pt.workspace_id = task.workspace_id AND pt.task_id = task.id
  )
LIMIT #{limit}

SELECT DISTINCT task_id FROM version_release_plan_task
WHERE workspace_id = #{workspaceId}
  AND task_id IN
  #{taskId}

SELECT id FROM task
WHERE workspace_id != #{workspaceId}
  AND id IN
#{id}

mapper.update:
UPDATE task SET owner = #{newName}
WHERE workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})
  AND (
    owner_user_id = #{userId}
    OR (
      owner_user_id IS NULL
      AND owner = #{oldName}
      AND NOT EXISTS (
        SELECT 1 FROM workspace_member m
        JOIN app_user u ON u.id = m.user_id
        WHERE m.workspace_id = task.workspace_id
          AND m.user_id <> #{userId}
          AND u.display_name = #{oldName}
      )
    )
  )

UPDATE task SET epic_id = NULL, updated_at = GREATEST(NOW(), DATE_ADD(updated_at, INTERVAL 1 SECOND))
WHERE workspace_id = #{workspaceId} AND epic_id IN
#{id}

UPDATE task t
SET t.owner_user_id = #{userId}
WHERE t.owner = #{displayName}
  AND t.owner_user_id IS NULL
  AND t.workspace_id IN (SELECT workspace_id FROM workspace_member WHERE user_id = #{userId})

mapper.sql:
AND (t.start_date IS NOT NULL OR t.due_date IS NOT NULL)

  AND t.gantt_end >= #{query.from}


  AND t.gantt_start <= #{query.to}

mapper.select:
SELECT task_id AS task_id, COUNT(*) AS cnt
FROM task_comment
WHERE workspace_id = #{workspaceId}
  AND task_id IN
  #{tid}
GROUP BY task_id

mapper.sql:
WHERE t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL


  AND t.created_at >= #{q.from} AND t.created_at < #{q.before}


  AND t.board_column = 'done'
  AND t.completed_at >= #{q.from} AND t.completed_at < #{q.before}


  AND COALESCE((SELECT cg.name FROM category cg
                WHERE cg.workspace_id = t.workspace_id AND cg.id = t.category_id), '') = #{q.value}


  AND COALESCE(t.owner, '') = #{q.value}

AND t.board_column = #{q.value}
AND t.priority = #{q.value}

mapper.select:
SELECT MAX(t.completed_at) FROM task t
WHERE t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL AND t.board_column = 'done'

AND t.req_id = #{reqId}

SELECT  FROM task t
WHERE t.workspace_id = #{workspaceId} AND t.deleted_at IS NULL AND t.board_column = 'done'

  AND t.req_id = #{reqId}
  AND t.completed_at >= #{from} AND t.completed_at < #{before}
ORDER BY t.completed_at DESC, BINARY t.id

SELECT title FROM task
WHERE workspace_id = #{workspaceId} AND deleted_at IS NULL
  AND req_id = #{reqId}
  AND title IS NOT NULL AND TRIM(title) <> ''
ORDER BY board_column, sort_order, id
LIMIT #{limit}

SELECT  FROM task
WHERE workspace_id = #{workspaceId} AND deleted_at IS NULL AND req_doc_id = #{reqDocId}
ORDER BY board_column, sort_order, id
LIMIT #{limit} OFFSET #{offset}
